import{_ as o,o as i,c as l,a2 as a}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"登录与多 profile","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/profile-login.md","filePath":"projects/lotus-plugin/docs/profile-login.md"}'),p={name:"projects/lotus-plugin/docs/profile-login.md"};function r(s,e,t,n,c,d){return i(),l("div",null,[...e[0]||(e[0]=[a(`<h1 id="登录与多-profile" tabindex="-1">登录与多 profile <a class="header-anchor" href="#登录与多-profile" aria-label="Permalink to &quot;登录与多 profile&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><p>一个 QQ 最多允许 <code>1..255</code> 个 Lotus profile。</p><ul><li><code>#扫码登录</code> 绑定 profile 1。</li><li><code>#扫码登录2</code> 绑定 profile 2。</li><li><code>#刷新cookie</code> 刷新当前 QQ 的全部 profile。</li><li><code>#刷新cookie2</code> 只刷新 profile 2。</li><li><code>#登录列表</code> 查看已创建 profile。</li><li><code>#清除登录2</code> 清除 profile 2 的敏感登录信息。</li></ul><p>profile 只是 Lotus 内部槽位，不等于米哈游 <code>ltuid</code>，也不等于游戏 UID。</p><p>登录成功后，荷花插件会保存：</p><ul><li>cookie</li><li>stoken</li><li>mid</li><li>ltoken</li><li>米哈游角色列表</li><li>genshin/miao 能识别的 NoteUser/MysUser 关系</li></ul><p>账号密码登录已经裁剪。外部插件的账号密码入口会被荷花插件阻断，并提示改用扫码登录。</p><h2 id="配置资料卡" tabindex="-1">配置资料卡 <a class="header-anchor" href="#配置资料卡" aria-label="Permalink to &quot;配置资料卡&quot;">​</a></h2><p>发送：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#荷花配置</span></span>
<span class="line"><span>#荷花配置2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>资料卡会显示登录态、设备、角色、签到开关和通知设置。敏感字段会脱敏。</p><p>相关小功能：</p><ul><li><a href="./features/device.html">设备信息-profile 绑定</a></li></ul><h2 id="旧登录格式自动修复" tabindex="-1">旧登录格式自动修复 <a class="header-anchor" href="#旧登录格式自动修复" aria-label="Permalink to &quot;旧登录格式自动修复&quot;">​</a></h2><p>本分支在插件启动 30 秒后自动扫描全部 profile，检测令牌放错 v1/v2 Cookie 字段、缺少相应 UID/MID、各处账号 UID 冲突或保存的 ltoken 不一致。发现问题后，用该 profile 的 stoken 同时重新获取 ltoken 和 cookie_token，成功后再保存；正常的旧版 Cookie 不会仅因版本旧而刷新。失败项每 6 小时复查，也可使用 <code>#刷新cookie</code> 手动重试。</p><p>扫码登录、手动刷新和自动修复共用同一套凭据生成逻辑。字段取决于接口实际返回的令牌：v1 与 v2 可以合法并存，不因 stoken 是 v2 就将所有 Cookie 强行写成 v2。刷新会核对返回账号，保留 profile 设置；接口失败或登录被更换时不覆盖原凭据，保存使用同目录临时文件原子替换。UID 会从账户字段、Cookie 和 stoken Cookie 的各个别名中核对；可信 stuid 相互冲突时保留原值并要求重新登录，不猜测账号归属。扫码保存或刷新进行期间清除登录，会使较旧操作失效；多个扫码结果交叠时，以较新开始保存的结果为准，网络请求不会占用账户写入锁。</p><p>自动修复也会同步 genshin 已加载的 Cookie 缓存。待同步状态仅保存 profile 标识，不保存令牌；同步失败后即使重启，也只补同步而不重复刷新凭据。启动时还会核对既有绑定的缓存差异，不为原本未桥接的正常账户新增绑定。扫描遇到损坏的 profile 文件会单独跳过，继续处理其他账户。</p><p>设备变更同样参与缓存同步和并发检查；不能只比较 Cookie 是否相同。明确指定 profile 的请求会把该上下文传到验证码和过期凭据刷新，避免同账号的另一个 profile 被误刷新。没有明确 profile 的外部请求，必须结合实际凭据和设备确认归属；无法唯一确认时，不自动刷新某个碰巧匹配 UID 的档案。</p><h2 id="扫码会话与凭据交换" tabindex="-1">扫码会话与凭据交换 <a class="header-anchor" href="#扫码会话与凭据交换" aria-label="Permalink to &quot;扫码会话与凭据交换&quot;">​</a></h2><p>二维码创建、确认轮询和扫码后的凭据交换使用同一个客户端会话。已有 profile 使用自己的设备 ID、FP 和设备资料；新 profile 先保存自己的虚拟设备，再用该设备创建独立会话；未取得与该 ID 配对的 FP 时省略 FP，不使用共享固定值。刷新多个 profile 时分别创建客户端，避免设备信息串用。</p><p>v2 stoken 的凭据交换使用 Passport 接口，携带该会话的设备信息、stoken/MID Cookie 和对应签名；v1 stoken 保留旧接口兼容。HTTP 410 不会触发盲目切换 POST 或重复交换。接口失败、返回账号 UID/MID 不符时保留原凭据，只有完整取得并核对令牌后才保存。</p>`,22)])])}const h=o(p,[["render",r]]);export{u as __pageData,h as default};
